INSERT INTO public.metabase_table VALUES (1, '2026-08-10 21:18:45.045238+00', '2026-08-10 21:18:45.045238+00', 'PEOPLE', 'Information on the user accounts registered with Sample Company.', 'entity/UserTable', true, 1, 'People', NULL, NULL, 'Is it? You tell us!', 'Note that employees and customer support staff will have accounts.', false, 'database', 'complete', false, NULL, NULL, 0, false, DEFAULT, NULL, NULL, NULL, 'unconfigured');
--;;
INSERT INTO public.metabase_table VALUES (2, '2026-08-10 21:18:45.045238+00', '2026-08-10 21:18:45.045238+00', 'ORDERS', 'Confirmed Sample Company orders for a product, from a user.', 'entity/TransactionTable', true, 1, 'Orders', NULL, NULL, 'Is it? You tell us!', 'You can join this on the Products and Orders table using the ID fields. Discount is left null if not applicable.', false, 'database', 'complete', false, NULL, NULL, 0, false, DEFAULT, NULL, NULL, NULL, 'unconfigured');
--;;
INSERT INTO public.metabase_table VALUES (3, '2026-08-10 21:18:45.045238+00', '2026-08-10 21:18:45.045238+00', 'PRODUCTS', 'Includes a catalog of all the products ever sold by the famed Sample Company.', 'entity/ProductTable', true, 1, 'Products', NULL, NULL, 'Is it? You tell us!', 'The rating column is an integer from 1-5 where 1 is dreadful and 5 is the best thing ever.', false, 'database', 'complete', false, NULL, NULL, 0, false, DEFAULT, NULL, NULL, NULL, 'unconfigured');
--;;
INSERT INTO public.metabase_table VALUES (4, '2026-08-10 21:18:45.045238+00', '2026-08-10 21:18:45.045238+00', 'REVIEWS', 'Reviews that Sample Company customers have left on our products.', 'entity/GenericTable', true, 1, 'Reviews', NULL, NULL, 'Is it? You tell us!', 'These reviews aren''t tied to orders so it is possible people have reviewed products they did not purchase from us.', false, 'database', 'complete', false, NULL, NULL, 0, false, DEFAULT, NULL, NULL, NULL, 'unconfigured');
--;;
INSERT INTO public.metabase_table VALUES (5, '2026-08-10 21:18:45.045238+00', '2026-08-10 21:18:45.045238+00', 'FEEDBACK', 'With each order of pies sent out, Piespace includes a place for customers to submit feedback and review their order.', 'entity/GenericTable', true, 1, 'Feedback', NULL, NULL, 'Is it? We’ll let you be the judge of that.', 'Not every account feels inclined to submit feedback. That’s cool. There’s still quite a few responses here.', false, 'database', 'complete', false, NULL, NULL, 0, false, DEFAULT, NULL, NULL, NULL, 'unconfigured');
--;;
INSERT INTO public.metabase_table VALUES (6, '2026-08-10 21:18:45.045238+00', '2026-08-10 21:18:45.045238+00', 'ACCOUNTS', 'Information on customer accounts registered with Piespace. Each account represents a new organization signing up for on-demand pies.', 'entity/UserTable', true, 1, 'Accounts', NULL, NULL, 'Is it? We’ll let you be the judge of that.', 'Piespace’s business operates with a two week trial period. If you see that “Canceled At” is null then that account is still happily paying for their pies.', false, 'database', 'complete', false, NULL, NULL, 0, false, DEFAULT, NULL, NULL, NULL, 'unconfigured');
--;;
INSERT INTO public.metabase_table VALUES (7, '2026-08-10 21:18:45.045238+00', '2026-08-10 21:18:45.045238+00', 'ANALYTIC_EVENTS', 'Piespace does some anonymous analytics tracking on how users interact with their platform. They’ve only had time to implement a few events, but you know how it is. Pies come first.', 'entity/EventTable', true, 1, 'Analytic Events', NULL, NULL, 'Is it? We’ll let you be the judge of that.', 'Piespace has cracked time travel, so keep in mind that some events may have already happened in the future.', false, 'database', 'complete', false, NULL, NULL, 0, false, DEFAULT, NULL, NULL, NULL, 'unconfigured');
--;;
INSERT INTO public.metabase_table VALUES (8, '2026-08-10 21:18:45.045238+00', '2026-08-10 21:18:45.045238+00', 'INVOICES', 'Confirmed payments from Piespace’s customers. Most accounts pay for their pie subscription on a monthly basis.', 'entity/GenericTable', true, 1, 'Invoices', NULL, NULL, 'Is it? We’ll let you be the judge of that.', 'You can group by “Account ID” to see all the payments from an account and unveil information like total amount paid to date.', false, 'database', 'complete', false, NULL, NULL, 0, false, DEFAULT, NULL, NULL, NULL, 'unconfigured');
--;;
